import { auth, db, watchAuth, loginWithStudentLogin, loginWithTeacherEmail, logout, createStudent, collection, doc, getDoc, getDocs, query, where, addDoc, setDoc, updateDoc, serverTimestamp } from "./firebase-service.js";

const $ = (s, p=document) => p.querySelector(s);
const app = $("#app");
const state = {view:"dashboard",role:"teacher",loginRole:"student",user:null,authLoading:true,year:"ЦЭ 2026",test:null,index:0,answers:{},optionOrder:{},timer:null,seconds:120*60,students:[],attempts:[],customTests:[],attemptId:null,saveTimer:null};
const scale={0:0,1:1,2:2,3:3,4:4,5:8,6:12,7:15,8:18,9:21,10:24,11:26,12:28,13:29,14:31,15:32,16:34,17:35,18:36,19:37,20:38,21:39,22:40,23:41,24:42,25:43,26:44,27:45,28:46,29:47,30:48,31:49,32:50,33:51,34:52,35:53,36:54,37:55,38:56,39:57,40:58,41:59,42:60,43:61,44:63,45:64,46:65,47:66,48:68,49:69,50:70,51:72,52:73,53:75,54:77,55:79,56:81,57:84,58:87,59:91,60:95,61:99,62:100};
const icons={dash:'<svg viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>',tests:'<svg viewBox="0 0 24 24"><path d="M6 3h12v18H6z"/><path d="M9 7h6M9 11h6M9 15h4"/></svg>',users:'<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3"/><path d="M3 20c0-4 2-6 6-6s6 2 6 6M16 5c3 0 4 2 4 4s-1 3-3 3M17 14c3 0 4 2 4 5"/></svg>',chart:'<svg viewBox="0 0 24 24"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg>'};
const teacherNav=[['dashboard','Главная','dash'],['tests','Тесты','tests'],['students','Учащиеся','users'],['results','Результаты','chart']];
const studentNav=[['student-home','Главная','dash'],['tests','Тесты','tests'],['student-results','Мои результаты','chart'],['mistakes','Мои ошибки','users']];

function shell(content,title,eyebrow='Кабинет учителя'){
  const nav=state.user.role==='teacher'?teacherNav:studentNav;const initials=state.user.name.split(' ').map(x=>x[0]).slice(0,2).join('');
  return `<div class="shell"><aside class="sidebar" id="sidebar"><div class="logo"><div class="logo-mark">ЦТ</div><div class="logo-copy"><strong>Английский язык</strong><span>ЦЭ / ЦТ · 2020–2026</span></div></div><nav class="nav">${nav.map(([id,label,ic])=>`<button data-view="${id}" class="${state.view===id?'active':''}">${icons[ic]}${label}</button>`).join('')}</nav><div class="sidebar-foot"><div class="user-mini"><div class="avatar">${initials}</div><div><strong>${state.user.name}</strong><span>${state.user.role==='teacher'?'Учитель':state.user.group}</span></div><button class="logout" id="logout" title="Выйти">↗</button></div></div></aside><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="mobile-menu" id="menuBtn">☰</button><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1></div></div><div class="actions"><button class="icon-btn" aria-label="Уведомления">⌁</button>${state.user.role==='teacher'?'<button class="primary" id="createStudentTop">+ Создать ученика</button>':''}</div></header>${content}</main><nav class="mobile-bar">${nav.map(([id,label])=>`<button data-view="${id}" class="${state.view===id?'active':''}">${label}</button>`).join('')}</nav></div>`;
}

function render(){clearInterval(state.timer);if(state.authLoading){app.innerHTML='<main class="loading-screen"><div class="logo-mark">ЦТ</div><p>Загрузка кабинета…</p></main>';return}if(!state.user)return renderLogin();if(state.view==='test')return renderTest();if(state.view==='result')return renderResult();const views={dashboard:dashboard(),tests:tests(),students:students(),results:results(),'student-home':studentDashboard(),'student-results':studentResults(),mistakes:mistakes()};const titles={dashboard:`Добрый вечер, ${state.user.name.split(' ')[0]}!`,tests:state.user.role==='teacher'?'Банк тестов':'Доступные тесты',students:'Учащиеся',results:'Результаты','student-home':`Привет, ${state.user.name.split(' ')[0]}!`,'student-results':'Мои результаты',mistakes:'Мои ошибки'};app.innerHTML=shell(views[state.view],titles[state.view],state.user.role==='teacher'?'Кабинет учителя':'Кабинет ученика');bindCommon();}
function bindCommon(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});$('#menuBtn')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#createStudentTop')?.addEventListener('click',createStudentModal);$('#logout')?.addEventListener('click',async()=>{await logout();state.view='dashboard'});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>startTest("ЦЭ 2026",+b.dataset.start));document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{state.year=b.dataset.year;render()});document.querySelectorAll('[data-open-test]').forEach(b=>b.onclick=()=>{const variant=TEST_DATA.variants.find(v=>v.id===b.dataset.openTest);if(variant?.status==='ready')launchTest(variant);else if(variant)sourceModal(variant)});document.querySelectorAll('[data-custom-test]').forEach(b=>b.onclick=()=>startCustomTest(b.dataset.customTest));$('#buildFromReady')?.addEventListener('click',customTestBuilderModal);$('#createManualTest')?.addEventListener('click',manualTestModal);document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>assignmentModal(b.dataset.modal));document.querySelectorAll('[data-attempt-errors]').forEach(b=>b.onclick=()=>showAttemptErrors(b.dataset.attemptErrors));document.querySelectorAll('[data-student-errors]').forEach(b=>b.onclick=()=>showStudentErrors(b.dataset.studentErrors));}

function renderLogin(){app.innerHTML=`<main class="login-page"><section class="brand-panel"><div class="login-brand"><div class="logo-mark">ЦТ</div><span>Английский язык</span></div><div><p class="eyebrow">Подготовка к ЦЭ и ЦТ</p><h1>Все тесты.<br>Весь прогресс.<br>В одном месте.</h1><p>Решайте варианты по годам, повторяйте ошибки и следите за результатом.</p></div><b>2020 — 2026</b></section><section class="login-side"><form class="login-card" id="loginForm"><p class="eyebrow">Добро пожаловать</p><h2>Вход в личный кабинет</h2><p>${state.loginRole==='teacher'?'Введите электронную почту учителя и пароль Firebase.':'Введите логин и пароль, которые выдал учитель.'}</p><div class="role-switch"><button type="button" data-role="student" class="${state.loginRole==='student'?'active':''}">Ученик</button><button type="button" data-role="teacher" class="${state.loginRole==='teacher'?'active':''}">Учитель</button></div><div class="field"><label>${state.loginRole==='teacher'?'Email':'Логин'}</label><input id="login" autocomplete="username" placeholder="${state.loginRole==='teacher'?'lukshaolga1982@gmail.com':'Введите логин'}" required></div><div class="field"><label>Пароль</label><div class="password-field"><input id="password" type="password" autocomplete="current-password" placeholder="Введите пароль" required><button type="button" id="showPassword">Показать</button></div></div><div id="loginError" class="login-error"></div><button class="primary login-submit" type="submit">Войти</button></form></section></main>`;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{state.loginRole=b.dataset.role;renderLogin()});$('#showPassword').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password'};$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;button.textContent='Вход…';$('#loginError').textContent='';try{if(state.loginRole==='teacher')await loginWithTeacherEmail($('#login').value,$('#password').value);else await loginWithStudentLogin($('#login').value,$('#password').value)}catch(error){console.error(error);$('#loginError').textContent='Не удалось войти. Проверьте логин, пароль и выбранную роль.';button.disabled=false;button.textContent='Войти'}}}

function dashboard(){const scored=state.attempts.filter(a=>a.status==='scored'),average=scored.length?Math.round(scored.reduce((s,a)=>s+(a.testScore??a.primaryScore??0),0)/scored.length):0;return `<section class="hero"><div class="hero-copy"><p class="eyebrow">Подготовка без лишнего</p><h2>Результаты учеников — ясно и по каждому заданию</h2><p>Назначайте варианты, собирайте собственные тесты и сразу замечайте темы, которые требуют повторения.</p><div class="hero-actions"><button class="primary" data-modal="assignment">Создать задание</button><button class="ghost" data-view="results">Посмотреть результаты</button></div></div><div class="hero-badge">ЦЭ<small>2026</small></div></section>
<section class="grid stats"><div class="stat"><div class="stat-head"><span>Учащиеся</span><em>реальные аккаунты</em></div><strong>${state.students.length}</strong></div><div class="stat"><div class="stat-head"><span>Средний балл</span><em>по завершённым</em></div><strong>${average}</strong></div><div class="stat"><div class="stat-head"><span>Работы на проверке</span><em>часть B</em></div><strong>${state.attempts.filter(a=>a.manualReviewStatus==='pending').length}</strong></div><div class="stat"><div class="stat-head"><span>Выполнено</span><em>все попытки</em></div><strong>${scored.length}</strong></div></section>
<section class="grid two-col"><div class="card"><div class="card-head"><h3>Текущие задания</h3><a data-view="tests">Все задания →</a></div>${assignment('A1–B22','Вариант 1 · до 26 августа',68,'due')}${assignment('B1–B8','Предлоги и вставка слов · 14 учеников',82,'')}${assignment('Работа над ошибками','Индивидуальная подборка',100,'done')}</div><div class="card"><div class="card-head"><h3>По блокам</h3><a data-view="results">Аналитика →</a></div><div class="block-bars">${[['A1–A4',86],['A5–A8',74],['A9–A12',68],['B1–B3',61],['B19–B22',57]].map(([b,v])=>`<div class="block-row"><span>${b}</span><div class="progress"><i style="width:${v}%"></i></div><b>${v}%</b></div>`).join('')}</div></div></section>`}
function assignment(name,meta,progress,status){return `<div class="assignment"><div class="assignment-icon">${name[0]}</div><div><strong>${name}</strong><span>${meta}</span><div class="progress"><i style="width:${progress}%"></i></div></div><span class="status ${status}">${status==='done'?'Выполнено':status==='due'?'Срок скоро':progress+'%'}</span></div>`}

function studentDashboard(){const completed=state.attempts.filter(a=>a.status==='scored'),best=completed.length?Math.max(...completed.map(a=>a.testScore||0)):0,totalErrors=completed.reduce((sum,a)=>sum+Object.values(a.questionResultsSnapshot||{}).filter(r=>!r.correct).length,0),progress=completed.length?Math.round(completed.reduce((s,a)=>s+(a.testScore||0),0)/completed.length):0;return `<section class="hero has-image"><div class="hero-copy"><p class="eyebrow">Твоя подготовка</p><h2>Продолжай в своём темпе</h2><p>Выбирай варианты 2025 и 2026 годов, отправляй ответы и следи за реальным прогрессом.</p><div class="hero-actions"><button class="primary" data-view="tests">Выбрать тест</button><button class="ghost" data-view="mistakes">Повторить ошибки</button></div></div><img class="hero-illustration" src="assets/study-hero.png" alt="Ученик готовится к тесту по английскому языку"></section><section class="grid stats"><div class="stat"><div class="stat-head"><span>Выполнено</span><em>все работы</em></div><strong>${completed.length}</strong></div><div class="stat"><div class="stat-head"><span>Лучший балл</span><em>из 100</em></div><strong>${best}</strong></div><div class="stat"><div class="stat-head"><span>Готовые тесты</span><em>2025–2026</em></div><strong>${TEST_DATA.readyCount}</strong></div><div class="stat"><div class="stat-head"><span>Все ошибки</span><em>за все тесты</em></div><strong>${totalErrors}</strong></div></section><section class="grid student-summary"><div class="card tracker"><div class="tracker-ring" style="--p:${progress}%"><div><strong>${progress}%</strong><span>общий прогресс</span></div></div><div><div class="card-head"><h3>Трекер прогресса</h3><span class="status done">по результатам</span></div><p>Показатель обновляется после каждой отправленной работы.</p></div></div><div class="card"><div class="card-head"><h3>Что делать дальше</h3><span class="error-total">${totalErrors} ошибок</span></div><p>Открой раздел «Тесты», выбери 2025 или 2026 год и один из десяти вариантов.</p><button class="secondary" data-view="tests">Перейти к тестам</button></div></section>`}
function studentResults(){return `<div class="section-title"><div><h2>История работ</h2><p>Твои сохранённые баллы и результаты.</p></div></div><div class="card table-wrap">${state.attempts.length?`<table class="table"><thead><tr><th>Работа</th><th>Первичный</th><th>Результат</th><th>Правильно</th></tr></thead><tbody>${state.attempts.map(a=>`<tr><td>${a.year||2026} · Вариант ${a.variantNumber||'—'}</td><td>${a.primaryScore??'—'} / ${a.maxPrimary??62}</td><td class="score">${a.testScore??'—'} / 100</td><td>${a.correctCount??'—'} / 40</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><strong>Работ пока нет</strong>Выберите готовый вариант 2025 или 2026 года и отправьте ответы.</div>'}</div>`}
function mistakes(){const wrong=[];state.attempts.forEach(a=>Object.entries(a.questionResultsSnapshot||{}).forEach(([id,r])=>{if(!r.correct)wrong.push(id)}));const unique=[...new Set(wrong)];return `<div class="section-title"><div><h2>${unique.length} заданий для повторения</h2><p>Счётчик построен по всем сохранённым попыткам.</p></div>${unique.length?'<button class="primary" onclick="startTest(2026,1)">Открыть тесты</button>':''}</div><div class="card">${unique.length?`<div class="q-grid">${unique.map(id=>`<span class="q-btn" style="display:grid;place-items:center">${id}</span>`).join('')}</div>`:'<div class="empty"><strong>Ошибок пока нет</strong>После первой работы здесь появятся задания для повторения.</div>'}</div>`}

function tests(){const meta=TEST_DATA.years.find(y=>y.year===state.year);const variants=TEST_DATA.variants.filter(v=>v.year===state.year);const customSection=`<section class="custom-tests-section"><div class="section-title"><div><h2>${state.user.role==='teacher'?'Мои тесты':'Тесты учителя'}</h2><p>${state.customTests.length?'Готовые авторские и составленные работы.':'Здесь появятся тесты, созданные учителем.'}</p></div>${state.user.role==='teacher'?'<div class="hero-actions"><button class="secondary" id="buildFromReady">Собрать из готовых</button><button class="primary" id="createManualTest">+ Создать новый тест</button></div>':''}</div>${state.customTests.length?`<div class="grid test-grid">${state.customTests.map((v,i)=>`<article class="test-card custom-test-card"><div class="stripe"></div><span class="year-badge">Авторский</span><div class="test-no">${i+1}</div><h3>${escapeAttr(v.title)}</h3><p>${v.questionCount||v.questions.length} заданий · ${escapeAttr(v.structure||'Составлено учителем')}</p><div class="test-meta"><span class="status done">Готов к решению</span><button class="secondary" data-custom-test="${escapeAttr(v.id)}">Решать</button></div></article>`).join('')}</div>`:'<div class="card empty"><strong>Авторских тестов пока нет</strong>Соберите работу из готовых заданий или заполните новый тест вручную.</div>'}</section>`;return `${customSection}<div class="section-title"><div><h2>Новый банк тестов</h2><p><strong>${state.year}</strong> · ${meta.variantCount} вариантов · ${meta.structure}</p></div></div><div class="filters">${TEST_DATA.years.map(y=>`<button class="filter ${y.year===state.year?'active':''}" data-year="${y.year}">${y.year}</button>`).join('')}</div><div class="content-notice"><strong>Все варианты перенесены в интерактивный формат</strong><span>Старый банк заменён заданиями из новых файлов.</span></div><div class="grid test-grid" style="margin-top:16px">${variants.map(v=>`<article class="test-card"><div class="stripe"></div><span class="year-badge">${v.year}</span><div class="test-no">${v.number}</div><h3>${v.title}</h3><p>${v.questionCount} заданий · ${v.structure}</p><div class="test-meta"><span class="status done">Готов к решению</span><button class="secondary" data-open-test="${v.id}">Решать</button></div></article>`).join('')}</div>`}

function students(){return `<div class="section-title"><div><h2>${state.students.length} учащихся</h2><p>Общий прогресс и счётчик ошибок по всем тестам.</p></div><button class="primary" onclick="createStudentModal()">+ Создать ученика</button></div><div class="card table-wrap">${state.students.length?`<table class="table"><thead><tr><th>Ученик</th><th>Логин</th><th>Группа</th><th>Выполнено</th><th>Все ошибки</th><th>Прогресс</th></tr></thead><tbody>${state.students.map(s=>`<tr><td><strong>${escapeAttr(s.displayName||'Без имени')}</strong></td><td><code>${escapeAttr(s.login||'—')}</code></td><td>${escapeAttr(s.groupId||'Без группы')}</td><td>${s.completedTests||0}</td><td><button class="secondary" data-student-errors="${escapeAttr(s.id)}">${s.totalErrors||0} · посмотреть</button></td><td><div class="progress" style="width:90px"><i style="width:${s.progressPercent||0}%"></i></div><small>${s.progressPercent||0}%</small></td></tr>`).join('')}</tbody></table>`:'<div class="empty"><strong>Учеников пока нет</strong>Создайте первый аккаунт — он сразу появится в этой таблице.</div>'}</div>`}

function results(){const studentName=id=>state.students.find(s=>s.id===id)?.displayName||'Ученик';return `<div class="section-title"><div><h2>Последние результаты</h2><p>Здесь появляются реальные работы после отправки учеником.</p></div></div><div class="card table-wrap" style="margin-top:16px">${state.attempts.length?`<table class="table"><thead><tr><th>Ученик</th><th>Год и работа</th><th>Первичный</th><th>Результат</th><th>Правильно</th><th>Ошибки</th></tr></thead><tbody>${state.attempts.map(a=>{const errorCount=Object.values(a.questionResultsSnapshot||{}).filter(r=>!r.correct).length;return `<tr><td><strong>${escapeAttr(studentName(a.studentId))}</strong></td><td>${a.year||2026} · Вариант ${a.variantNumber||'—'}</td><td>${a.primaryScore??'—'} / ${a.maxPrimary??62}</td><td class="score">${a.testScore??'—'} / 100</td><td>${a.correctCount??'—'}</td><td>${a.status==='scored'?`<button class="secondary" data-attempt-errors="${escapeAttr(a.id)}">${errorCount} · открыть</button>`:'Ожидает проверки'}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty"><strong>Результатов пока нет</strong>После первой отправленной работы она появится здесь.</div>'}</div>`}

function testForAttempt(attempt){return TEST_DATA.variants.find(v=>v.id===attempt.testId)||state.customTests.find(v=>v.id===attempt.testId)||(TEST_DATA.variants.find(v=>v.year===attempt.year&&v.number===attempt.variantNumber))}
function correctAnswerFor(attempt,questionId){const question=testForAttempt(attempt)?.questions.find(q=>q.id===questionId);const values=question?.accepted||(question?.answer!==undefined?[question.answer]:[]);return values.filter(value=>value!==undefined&&value!==null).join(' / ')||'Ключ не найден'}
function errorRows(attempt){return Object.entries(attempt.questionResultsSnapshot||{}).filter(([,result])=>!result.correct).map(([questionId,result])=>({attempt,questionId,studentAnswer:result.studentAnswer||'Нет ответа',correctAnswer:result.correctAnswer||correctAnswerFor(attempt,questionId)}))}
function errorsTable(rows){return rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Тест</th><th>Задание</th><th>Ответ ученика</th><th>Правильный ответ</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${row.attempt.year||'—'} · Вариант ${row.attempt.variantNumber||'—'}</td><td><strong>${escapeAttr(row.questionId)}</strong></td><td><span class="error-total">${escapeAttr(row.studentAnswer)}</span></td><td><strong>${escapeAttr(row.correctAnswer)}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Ошибок нет</strong>В этой работе все ответы правильные.</div>'}
function showAttemptErrors(attemptId){const attempt=state.attempts.find(item=>item.id===attemptId);if(!attempt)return toast('Работа не найдена');const student=state.students.find(item=>item.id===attempt.studentId);modal(`<div class="card-head"><div><p class="eyebrow">Разбор работы</p><h2>${escapeAttr(student?.displayName||'Ученик')}</h2><p>${attempt.year||'—'} · Вариант ${attempt.variantNumber||'—'}</p></div><button class="ghost" data-close>Закрыть</button></div>${errorsTable(errorRows(attempt))}`,true)}
function showStudentErrors(studentId){const student=state.students.find(item=>item.id===studentId);const attempts=state.attempts.filter(item=>item.studentId===studentId&&item.status==='scored');const rows=attempts.flatMap(errorRows);modal(`<div class="card-head"><div><p class="eyebrow">Все сохранённые ошибки</p><h2>${escapeAttr(student?.displayName||'Ученик')}</h2><p>${attempts.length} завершённых работ · ${rows.length} ошибок</p></div><button class="ghost" data-close>Закрыть</button></div>${errorsTable(rows)}`,true)}

function shuffledOptions(options){const result=[...(options||[])];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function createOptionOrder(variant){return Object.fromEntries(variant.questions.filter(q=>q.type==='choice'||q.type==='inline-choice').map(q=>[q.id,shuffledOptions(q.options)]))}
function optionsFor(q){return state.optionOrder[q.id]||q.options||[]}
async function launchTest(variant){state.test=variant;state.index=0;state.answers={};state.optionOrder=createOptionOrder(variant);state.seconds=(variant.timeLimit||120)*60;state.attemptId=null;if(state.user?.role==='student'){try{const attempt=await addDoc(collection(db,"attempts"),{studentId:state.user.uid,teacherId:state.user.createdBy,testId:variant.id,year:variant.year||'Авторский',variantNumber:variant.number||variant.title,status:"in-progress",questionsSnapshot:variant.questions.map(q=>({id:q.id,section:q.section,block:q.block||q.section})),answersSnapshot:{},startedAt:serverTimestamp(),createdAt:serverTimestamp()});state.attemptId=attempt.id}catch(error){console.error(error);toast('Не удалось начать тест. Проверьте профиль ученика и правила Firestore.');return}}state.view='test';render()}
async function startTest(year,number){const variant=TEST_DATA.variants.find(v=>v.year===year&&v.number===number&&v.status==='ready');if(!variant){toast('Этот вариант ещё переносится в интерактивный формат');return}await launchTest(variant)}
async function startCustomTest(testId){let variant=state.customTests.find(v=>v.id===testId);if(!variant)return toast('Тест не найден');if(state.user.role==='teacher'){try{const keySnap=await getDoc(doc(db,"answerKeys",testId)),keys=keySnap.data()?.answers||{};variant={...variant,questions:variant.questions.map(q=>({...q,accepted:keys[q.id]||[]}))}}catch(error){console.error(error)}}await launchTest(variant)}
function renderTest(){const q=state.test.questions[state.index];const pdf=`${state.test.sourceUrl}#page=${state.test.pageStart}&view=FitH`;app.innerHTML=shell(`<div class="source-test-layout"><section class="source-panel card"><div class="card-head"><div><h3>Оригинальный сборник · страницы ${state.test.pages}</h3><p>Найдите задание ${q.id} и внесите ответ справа.</p></div><a class="secondary" href="${pdf}" target="_blank" rel="noopener">Открыть отдельно ↗</a></div><object class="source-pdf" data="${pdf}" type="application/pdf"><div class="pdf-fallback"><p>Встроенный просмотр PDF недоступен в этом браузере.</p><a class="primary" href="${pdf}" target="_blank" rel="noopener">Открыть сборник</a></div></object></section><aside class="answer-panel"><div class="card question-card"><div class="card-head"><span class="question-id">${q.id}</span><span class="status">${q.block}</span></div><h2>${q.prompt}</h2>${questionBody(q)}<div class="test-nav"><button class="ghost" id="prev" ${state.index===0?'disabled':''}>← Назад</button><button class="primary" id="next">${state.index===state.test.questions.length-1?'Завершить':'Далее →'}</button></div></div><div class="card answer-map"><div class="card-head"><h3>Бланк ответов</h3><span class="timer" id="timer">120:00</span></div><div class="q-grid">${state.test.questions.map((x,i)=>`<button class="q-btn ${isQuestionAnswered(x)?'answered':''} ${i===state.index?'current':''}" data-q="${i}">${x.id}</button>`).join('')}</div><div class="progress"><i style="width:${Math.round(answeredTaskCount()/totalTaskCount()*100)}%"></i></div><p class="autosave-note">Заполнено ${answeredTaskCount()} из ${totalTaskCount()}. Ответы сохраняются во время работы.</p></div></aside></div>`,'Тестирование',`${state.test.year} · Вариант ${state.test.number}`);bindCommon();bindQuestionInputs(q);document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{saveText(q);state.index=+b.dataset.q;renderTest()});$('#prev').onclick=()=>{saveText(q);if(state.index>0)state.index--;renderTest()};$('#next').onclick=()=>{saveText(q);if(state.index<state.test.questions.length-1){state.index++;renderTest()}else confirmFinish()};startTimer()}
function questionBody(q){if(q.type==='choice')return `<div class="context">${q.context}</div><div class="options">${optionsFor(q).map((o,i)=>`<button class="option ${state.answers[q.id]===o?'selected':''}" data-answer="${escapeAttr(o)}"><b>${String.fromCharCode(65+i)}</b>${o}</button>`).join('')}</div>`;if(q.type==='inline-choice')return `<div class="inline-task">${q.before}<select class="inline-select" id="inlineSelect"><option value="">выберите…</option>${optionsFor(q).map(o=>`<option ${state.answers[q.id]===o?'selected':''}>${o}</option>`).join('')}</select>${q.after}</div>`;if(q.type==='group-input')return `<div class="group-tasks">${q.items.map((item,i)=>`<div class="group-row"><b>${i+1}.</b><span>${item.before}<input class="inline-input" data-item="${item.id}" value="${escapeAttr(state.answers[item.id]||'')}" autocomplete="off" aria-label="Ответ ${item.id}">${item.after}</span></div>`).join('')}</div>`;return `<div class="context">${q.context}</div><input class="answer-input" id="textAnswer" value="${escapeAttr(state.answers[q.id]||'')}" placeholder="Введите ответ" autocomplete="off">`}
function bindQuestionInputs(q){document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.answers[q.id]=b.dataset.answer;persistProgress();renderTest()});$('#inlineSelect')?.addEventListener('change',e=>{state.answers[q.id]=e.target.value;persistProgress();renderTest()});$('#textAnswer')?.addEventListener('input',e=>{state.answers[q.id]=e.target.value;persistProgress()});document.querySelectorAll('[data-item]').forEach(i=>i.addEventListener('input',e=>{state.answers[e.target.dataset.item]=e.target.value;persistProgress()}))}
function totalTaskCount(){return state.test.questions.reduce((n,q)=>n+(q.items?.length||1),0)}
function answeredTaskCount(){return state.test.questions.reduce((n,q)=>n+(q.items?q.items.filter(i=>state.answers[i.id]).length:(state.answers[q.id]?1:0)),0)}
function isQuestionAnswered(q){return q.items?q.items.every(i=>state.answers[i.id]):Boolean(state.answers[q.id])}
function saveText(q){if(q.type==='input'&&$('#textAnswer'))state.answers[q.id]=$('#textAnswer').value;persistProgress()}
function persistProgress(){if(!state.attemptId||state.user?.role!=='student')return;clearTimeout(state.saveTimer);state.saveTimer=setTimeout(async()=>{try{await updateDoc(doc(db,"attempts",state.attemptId),{answersSnapshot:{...state.answers},lastSavedAt:serverTimestamp()})}catch(error){console.error(error);toast('Не удалось сохранить ответы в облаке')}},450)}
function startTimer(){clearInterval(state.timer);const paint=()=>{const el=$('#timer');if(el)el.textContent=`${String(Math.floor(state.seconds/60)).padStart(2,'0')}:${String(state.seconds%60).padStart(2,'0')}`};paint();state.timer=setInterval(()=>{state.seconds--;paint();if(state.seconds<=0){clearInterval(state.timer);finishTest()}},1000)}
function confirmFinish(){modal(`<h2>Завершить тест?</h2><p>Вы ответили на ${answeredTaskCount()} из ${totalTaskCount()} заданий. После отправки изменить ответы нельзя.</p><div class="modal-actions"><button class="ghost" data-close>Вернуться</button><button class="primary" id="finish">Отправить ответы</button></div>`);$('#finish').onclick=finishTest}
function normalize(v){return String(v||'').trim().toLowerCase().replace(/[’‘`]/g,"'").replace(/[–—−]/g,'-').replace(/\s+/g,' ')}
async function finishTest(){clearInterval(state.timer);clearTimeout(state.saveTimer);closeModal();if(state.user.role==='teacher'){let primary=0,correct=0;const max=state.test.questions.reduce((sum,q)=>sum+(q.points||(q.section==='A'?1:2)),0);state.test.questions.forEach(q=>{const ok=(q.accepted||[q.answer]).some(a=>normalize(a)===normalize(state.answers[q.id]));if(ok){primary+=q.points||(q.section==='A'?1:2);correct++}});const percent=max?Math.round(primary/max*100):0;state.result={primary,max,correct,total:state.test.questions.length,percent,testScore:max===62?scale[primary]:percent};state.view='result';render();return}if(!state.attemptId){toast('Попытка не была создана');state.view='student-home';render();return}modal('<h2>Отправляем работу…</h2><p>Ответы сохраняются в кабинете учителя.</p>');try{await updateDoc(doc(db,"attempts",state.attemptId),{answersSnapshot:{...state.answers},status:"submitted",submittedAt:serverTimestamp(),lastSavedAt:serverTimestamp()});state.result={pending:true,total:totalTaskCount(),answered:answeredTaskCount()};state.attemptId=null;await loadAccountData();closeModal();state.view='result';render()}catch(error){console.error(error);closeModal();toast('Не удалось отправить работу. Проверьте правила Firestore.')}}
function renderResult(){const r=state.result,custom=state.test?.kind==='custom';app.innerHTML=shell(`<div class="card" style="max-width:760px;margin:20px auto;text-align:center"><p class="eyebrow">Работа завершена</p><h2>Результат сохранён</h2><div class="result-ring" style="--score:${r.percent}%"><div><strong>${r.testScore??r.percent}</strong><span>из 100</span></div></div><div class="grid result-stats"><div class="stat"><span>Первичный балл</span><strong>${r.primary} / ${r.max}</strong></div><div class="stat"><span>Правильных</span><strong>${r.correct} / ${r.total}</strong></div><div class="stat"><span>Время</span><strong>${(state.test.timeLimit||120)-Math.floor(state.seconds/60)} мин</strong></div></div><p>Правильные ответы будут доступны по настройке учителя.</p><div class="hero-actions" style="justify-content:center"><button class="primary" data-view="results">К результатам</button><button class="ghost" ${custom?`data-custom-test="${escapeAttr(state.test.id)}"`:`onclick="startTest(state.test.year,state.test.number)"`}>Повторить тест</button></div></div>`,'Результат',custom?state.test.title:`${state.test.year} · Вариант ${state.test.number}`);bindCommon()}

function sourceModal(variant){const meta=TEST_DATA.years.find(y=>y.year===variant.year);modal(`<h2>${variant.year} · ${variant.title}</h2><p>Источник <strong>${meta.source}</strong> добавлен в каталог. Оригинальная структура: ${variant.structure}, всего ${variant.questionCount} заданий.</p><p>Этот вариант ожидает точного переноса текста и ручной сверки ключей. До завершения проверки ученикам он не назначается.</p><div class="modal-actions"><button class="primary" data-close>Понятно</button></div>`)}

function createStudentModal(){modal(`<h2>Создать аккаунт ученика</h2><p>Ученик войдёт в свой кабинет по логину и паролю, которые вы ему сообщите.</p><div class="form-grid"><div class="field"><label>Имя и фамилия</label><input id="studentName" placeholder="Марта Коваль" required></div><div class="field"><label>Группа</label><select id="studentGroup"><option>11 класс</option><option>10 класс</option><option>Без группы</option></select></div><div class="field"><label>Логин</label><input id="studentLogin" placeholder="marta" autocomplete="off" required></div><div class="field"><label>Пароль</label><input id="studentPassword" type="password" placeholder="Не менее 8 символов" autocomplete="new-password" required></div></div><div class="modal-actions"><button class="ghost" data-close>Отмена</button><button class="primary" id="makeStudent">Создать аккаунт</button></div>`);$('#makeStudent').onclick=async()=>{const button=$('#makeStudent'),displayName=$('#studentName').value.trim(),login=normalize($('#studentLogin').value),password=$('#studentPassword').value,groupId=$('#studentGroup').value;if(!displayName||login.length<3||password.length<8){toast('Заполните имя, логин и пароль от 8 символов');return}button.disabled=true;button.textContent='Создание…';try{await createStudent({displayName,login,password,groupId});await loadAccountData();closeModal();render();toast(`Аккаунт ${login} создан`)}catch(error){console.error(error);button.disabled=false;button.textContent='Создать аккаунт';toast(error.message||'Не удалось создать ученика')}}}
function cleanFirestoreValue(value){return JSON.parse(JSON.stringify(value))}
function questionWithoutKey(question){const copy=cleanFirestoreValue(question);delete copy.answer;delete copy.accepted;return copy}
async function saveTeacherTest(title,questions,structure='Авторский тест',timeLimit=120){
  const id=`custom-${state.user.uid}-${Date.now()}`,publicQuestions=questions.map(questionWithoutKey);
  const answers=Object.fromEntries(questions.map(q=>[q.id,(q.accepted||(q.answer!==undefined?[q.answer]:[])).filter(v=>v!==undefined&&v!==null)]));
  const documentData={title,teacherId:state.user.uid,kind:'custom',year:'Авторский',variantNumber:title,number:title,questionCount:questions.length,status:'published',format:'interactive',structure,questions:publicQuestions,timeLimit,createdAt:serverTimestamp(),updatedAt:serverTimestamp()};
  await setDoc(doc(db,'tests',id),documentData);
  await setDoc(doc(db,'answerKeys',id),{answers,teacherId:state.user.uid,updatedAt:serverTimestamp()});
  await loadCustomTests();closeModal();render();toast('Тест создан и доступен ученикам');
}
function readyQuestionSources(){return TEST_DATA.variants.filter(v=>v.status==='ready').flatMap(test=>test.questions.map(question=>({key:`${test.id}::${question.id}`,test,question})))}
function customTestBuilderModal(){
  const sources=readyQuestionSources(),selected=new Set();
  modal(`<div class="card-head"><div><p class="eyebrow">Конструктор</p><h2>Собрать тест из готовых заданий</h2><p>Фильтруйте банк и отмечайте нужные задания.</p></div><button class="ghost" data-close>Закрыть</button></div><div class="form-grid builder-filters"><div class="field"><label>Название теста</label><input id="builderTitle" placeholder="Повторение грамматики"></div><div class="field"><label>Год</label><select id="builderYear"><option value="all">Все годы</option><option>2026</option><option>2025</option></select></div><div class="field"><label>Вариант</label><select id="builderVariant"><option value="all">Все варианты</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}">Вариант ${i+1}</option>`).join('')}</select></div><div class="field"><label>Блок</label><select id="builderBlock"><option value="all">Все блоки</option>${['A1–A4','A5–A8','A9–A12','A13–A14','A15–A18','B1–B3','B4–B6','B7–B8','B9–B18','B19–B22'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="builder-toolbar"><strong id="selectedCount">Выбрано: 0</strong><button class="secondary" id="selectVisible">Выбрать показанные</button></div><div class="question-picker" id="questionPicker"></div><div class="modal-actions"><button class="ghost" data-close>Отмена</button><button class="primary" id="saveBuiltTest">Создать тест</button></div>`,true);
  const paint=()=>{const year=$('#builderYear').value,variant=$('#builderVariant').value,block=$('#builderBlock').value;const visible=sources.filter(item=>(year==='all'||String(item.test.year)===year)&&(variant==='all'||String(item.test.number)===variant)&&(block==='all'||item.question.block===block));$('#questionPicker').innerHTML=visible.map(item=>`<label class="picker-item"><input type="checkbox" data-source-key="${escapeAttr(item.key)}" ${selected.has(item.key)?'checked':''}><span><strong>${item.test.year} · Вариант ${item.test.number} · ${escapeAttr(item.question.id)}</strong><small>${escapeAttr(item.question.block||item.question.section)} · ${escapeAttr(item.question.prompt||'Задание')}</small></span></label>`).join('')||'<div class="empty">По выбранным фильтрам заданий нет.</div>';document.querySelectorAll('[data-source-key]').forEach(input=>input.onchange=()=>{input.checked?selected.add(input.dataset.sourceKey):selected.delete(input.dataset.sourceKey);$('#selectedCount').textContent=`Выбрано: ${selected.size}`});$('#selectVisible').onclick=()=>{visible.forEach(item=>selected.add(item.key));paint()}};
  ['builderYear','builderVariant','builderBlock'].forEach(id=>$(`#${id}`).onchange=paint);paint();
  $('#saveBuiltTest').onclick=async()=>{const title=$('#builderTitle').value.trim();if(!title)return toast('Введите название теста');if(!selected.size)return toast('Выберите хотя бы одно задание');const chosen=sources.filter(item=>selected.has(item.key)).map((item,index)=>{const q=cleanFirestoreValue(item.question);q.sourceLabel=`${item.test.year} · Вариант ${item.test.number} · ${q.id}`;q.id=`Q${index+1}`;q.points=q.section==='A'?1:2;return q});const button=$('#saveBuiltTest');button.disabled=true;button.textContent='Сохранение…';try{await saveTeacherTest(title,chosen,'Составлен из готовых заданий')}catch(error){console.error(error);button.disabled=false;button.textContent='Создать тест';toast('Не удалось сохранить тест. Проверьте правила Firestore.')}};
}
function manualQuestionRow(index){return `<section class="manual-question" data-manual-question><div class="card-head"><strong>Задание ${index}</strong><button class="ghost remove-question" type="button">Удалить</button></div><div class="form-grid"><div class="field"><label>Номер задания</label><input class="mq-id" value="${index}" placeholder="A1"></div><div class="field"><label>Часть</label><select class="mq-section"><option value="A">A · 1 балл</option><option value="B">B · 2 балла</option></select></div><div class="field"><label>Тип ответа</label><select class="mq-type"><option value="choice">Выбор варианта</option><option value="text">Ввод слова или фразы</option></select></div><div class="field"><label>Блок</label><input class="mq-block" placeholder="A1–A4"></div></div><div class="field"><label>Инструкция</label><input class="mq-prompt" placeholder="Выберите правильный вариант."></div><div class="field"><label>Текст задания</label><textarea class="mq-context" rows="4" placeholder="Введите предложение или полный текст с пропуском…"></textarea></div><div class="form-grid"><div class="field"><label>Варианты ответа — каждый с новой строки</label><textarea class="mq-options" rows="5" placeholder="has turned&#10;will turn&#10;is turned"></textarea></div><div class="field"><label>Правильные ответы — каждый с новой строки</label><textarea class="mq-answers" rows="5" placeholder="is turned"></textarea></div></div></section>`}
function manualTestModal(){
  let count=1;modal(`<div class="card-head"><div><p class="eyebrow">Новый материал</p><h2>Создать новый тест</h2><p>Добавьте собственные задания. Для части B можно указать несколько допустимых ответов.</p></div><button class="ghost" data-close>Закрыть</button></div><div class="form-grid"><div class="field"><label>Название теста</label><input id="manualTitle" placeholder="Тест по предлогам"></div><div class="field"><label>Ограничение времени, минут</label><input id="manualTime" type="number" min="1" value="45"></div></div><div id="manualQuestions">${manualQuestionRow(1)}</div><button class="secondary" id="addManualQuestion" type="button">+ Добавить задание</button><div class="modal-actions"><button class="ghost" data-close>Отмена</button><button class="primary" id="saveManualTest">Сохранить тест</button></div>`,true);
  const bindRemove=()=>document.querySelectorAll('.remove-question').forEach(button=>button.onclick=()=>{if(document.querySelectorAll('[data-manual-question]').length===1)return toast('В тесте должно остаться хотя бы одно задание');button.closest('[data-manual-question]').remove()});bindRemove();$('#addManualQuestion').onclick=()=>{$('#manualQuestions').insertAdjacentHTML('beforeend',manualQuestionRow(++count));bindRemove()};
  $('#saveManualTest').onclick=async()=>{const title=$('#manualTitle').value.trim();if(!title)return toast('Введите название теста');const timeLimit=Math.max(1,+$('#manualTime').value||45),questions=[];for(const [index,row] of [...document.querySelectorAll('[data-manual-question]')].entries()){const id=$('.mq-id',row).value.trim()||String(index+1),section=$('.mq-section',row).value,type=$('.mq-type',row).value,prompt=$('.mq-prompt',row).value.trim(),context=$('.mq-context',row).value.trim(),options=$('.mq-options',row).value.split('\n').map(v=>v.trim()).filter(Boolean),accepted=$('.mq-answers',row).value.split('\n').map(v=>v.trim()).filter(Boolean);if(questions.some(question=>question.id===id))return toast(`Номер задания ${id} повторяется`);if(!context||!accepted.length)return toast(`Заполните текст и правильный ответ в задании ${index+1}`);if(type==='choice'&&options.length<2)return toast(`Добавьте минимум два варианта в задании ${index+1}`);questions.push({id,section,block:$('.mq-block',row).value.trim()||section,type,prompt:prompt||'Выполните задание.',context,options:type==='choice'?options:[],accepted,answer:accepted[0],points:section==='A'?1:2})}const button=$('#saveManualTest');button.disabled=true;button.textContent='Сохранение…';try{await saveTeacherTest(title,questions,'Создан учителем',timeLimit)}catch(error){console.error(error);button.disabled=false;button.textContent='Сохранить тест';toast('Не удалось сохранить тест. Проверьте правила Firestore.')}};
}
function assignmentModal(type){modal(`<h2>${type==='custom'?'Собрать тест':'Новое задание'}</h2><p>Выберите режим и правила выполнения.</p><div class="field"><label>Режим</label><select><option>Полный тест A1–B22</option><option>Тренировка по блокам</option><option>Тест из выбранных заданий</option><option>Случайная подборка</option><option>Повторение ошибок</option></select></div><div class="form-grid"><div class="field"><label>Попыток</label><input type="number" value="2" min="1"></div><div class="field"><label>Время, минут</label><input type="number" value="120" min="1"></div><div class="field"><label>Дата окончания</label><input type="date"></div><div class="field"><label>Ответы</label><select><option>После дедлайна</option><option>Сразу</option><option>После всех попыток</option><option>Не показывать</option></select></div></div><div class="modal-actions"><button class="ghost" data-close>Отмена</button><button class="primary" id="saveAssignment">Продолжить</button></div>`);$('#saveAssignment').onclick=()=>{closeModal();toast('Задание сохранено как черновик')}}
function modal(html,wide=false){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal ${wide?'modal-wide':''}">${html}</div></div>`);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()}}
function closeModal(){$('#modal')?.remove()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function escapeAttr(v){return String(v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')}
const renderTextQuestionBody = questionBody;
questionBody = function renderQuestionBody(q){
  if(!q.image)return renderTextQuestionBody(q);
  const image=`<figure class="task-sheet"><img src="${q.image}" alt="Страница с заданиями, содержащая ${q.id}" loading="eager"></figure>`;
  if(q.type==='choice')return `${image}<div class="options compact-options">${optionsFor(q).map((o,i)=>`<button class="option ${state.answers[q.id]===o?'selected':''}" data-answer="${escapeAttr(o)}"><b>${i+1}</b>Вариант ${o}</button>`).join('')}</div>`;
  return `${image}<input class="answer-input" id="textAnswer" value="${escapeAttr(state.answers[q.id]||'')}" placeholder="Введите ответ для ${q.id}" autocomplete="off">`;
};

const renderPdfTest = renderTest;
renderTest = function renderCurrentTest(){
  if(state.test?.format !== 'interactive') return renderPdfTest();
  const q=state.test.questions[state.index];
  app.innerHTML=shell(`<div class="test-layout interactive-layout"><section class="card question-card interactive-question"><div class="card-head"><span class="question-id">${q.id}</span><span class="status">${q.block}</span></div>${q.sourceLabel?`<p class="source-label">Источник: ${escapeAttr(q.sourceLabel)}</p>`:''}<h2>${q.prompt}</h2>${questionBody(q)}<div class="test-nav"><button class="ghost" id="prev" ${state.index===0?'disabled':''}>← Назад</button><button class="primary" id="next">${state.index===state.test.questions.length-1?'Завершить':'Далее →'}</button></div></section><aside class="test-side"><div class="card"><div class="card-head"><h3>${state.test.kind==='custom'?escapeAttr(state.test.title):`${state.test.year} · Вариант ${state.test.number}`}</h3><span class="timer" id="timer">${state.test.timeLimit||120}:00</span></div><div class="q-grid">${state.test.questions.map((x,i)=>`<button class="q-btn ${isQuestionAnswered(x)?'answered':''} ${i===state.index?'current':''}" data-q="${i}">${x.id}</button>`).join('')}</div><div class="progress" style="margin-top:18px"><i style="width:${Math.round(answeredTaskCount()/totalTaskCount()*100)}%"></i></div><p class="autosave-note">Заполнено ${answeredTaskCount()} из ${totalTaskCount()}.</p></div></aside></div>`,'Тестирование',state.test.kind==='custom'?state.test.title:`${state.test.year} · Вариант ${state.test.number}`);
  bindCommon();
  bindQuestionInputs(q);
  document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{saveText(q);state.index=+b.dataset.q;renderTest()});
  $('#prev').onclick=()=>{saveText(q);if(state.index>0)state.index--;renderTest()};
  $('#next').onclick=()=>{saveText(q);if(state.index<state.test.questions.length-1){state.index++;renderTest()}else confirmFinish()};
  startTimer();
};

const renderScoredResult = renderResult;
renderResult = function renderCurrentResult(){
  if(!state.result?.pending) return renderScoredResult();
  app.innerHTML=shell(`<div class="card" style="max-width:760px;margin:20px auto;text-align:center"><p class="eyebrow">Работа отправлена</p><h2>Ответы сохранены</h2><div class="result-ring" style="--score:100%"><div><strong>✓</strong><span>в Firestore</span></div></div><div class="grid result-stats"><div class="stat"><span>Заполнено</span><strong>${state.result.answered} / ${state.result.total}</strong></div><div class="stat"><span>Статус</span><strong>На проверке</strong></div><div class="stat"><span>Проверит</span><strong>Учитель</strong></div></div><p>Результат появится в разделе «Мои результаты» после входа учителя.</p><div class="hero-actions" style="justify-content:center"><button class="primary" data-view="student-results">К моим результатам</button><button class="ghost" data-view="tests">К тестам</button></div></div>`,'Работа отправлена',`${state.test.year} · Вариант ${state.test.number}`);
  bindCommon();
};

const renderTestsCatalog = tests;
tests = function render2026Catalog(){
  return renderTestsCatalog().replace('5 полных вариантов готовы к решению','10 вариантов 2026 готовы к решению').replace('Задания открываются из оригинального сборника, ответы вводятся в интерактивный бланк.','Каждый вариант открывается отдельно, ответы вводятся в интерактивный бланк.');
};

async function scoreSubmittedAttempts(){
  const pending=state.attempts.filter(a=>a.status==='submitted');
  for(const attempt of pending){
    const keySnap=await getDoc(doc(db,"answerKeys",attempt.testId));
    const keys=keySnap.data()?.answers||{};
    let primary=0,correct=0;
    const results={};
    for(const q of attempt.questionsSnapshot||[]){
      const ok=(keys[q.id]||[]).some(a=>normalize(a)===normalize(attempt.answersSnapshot?.[q.id]));
      const points=ok?(q.section==='A'?1:2):0;
      primary+=points;if(ok)correct++;
      results[q.id]={correct:ok,points,studentAnswer:attempt.answersSnapshot?.[q.id]||'',correctAnswer:(keys[q.id]||[]).join(' / ')};
    }
    const max=(attempt.questionsSnapshot||[]).reduce((n,q)=>n+(q.section==='A'?1:2),0);
    const testScore=max===62?scale[primary]:(max?Math.round(primary/max*100):0);
    await updateDoc(doc(db,"attempts",attempt.id),{status:"scored",scoredAt:serverTimestamp(),primaryScore:primary,testScore,correctCount:correct,maxPrimary:max,questionResultsSnapshot:results,manualReviewStatus:"available",scaleVersion:max===62?'2026':'percent'});
    const studentRef=doc(db,"users",attempt.studentId),studentSnap=await getDoc(studentRef),student=studentSnap.data()||{},wrong=(attempt.questionsSnapshot||[]).length-correct;
    await updateDoc(studentRef,{totalErrors:(student.totalErrors||0)+wrong,completedTests:(student.completedTests||0)+1,lastPrimaryScore:primary,lastTestScore:testScore,lastActivityAt:serverTimestamp()});
  }
  return pending.length;
}

async function publishBuiltInTests(){
  for(const test of TEST_DATA.variants.filter(v=>v.status==='ready')){
    const answers=Object.fromEntries(test.questions.flatMap(q=>{
      const accepted=(q.accepted||(q.answer!==undefined?[q.answer]:[])).filter(value=>value!==undefined&&value!==null);
      return accepted.length?[[q.id,accepted]]:[];
    }));
    const testDocument={title:test.title,year:test.year,variantNumber:test.number,questionCount:test.questionCount,status:"published",updatedAt:serverTimestamp()};
    for(const field of ["structure","sourceUrl","pageStart","pages"]){if(test[field]!==undefined&&test[field]!==null)testDocument[field]=test[field]}
    await setDoc(doc(db,"tests",test.id),testDocument,{merge:true});
    await setDoc(doc(db,"answerKeys",test.id),{answers,updatedAt:serverTimestamp()},{merge:true});
  }
}

async function loadCustomTests(){
  const ownerId=state.user.role==='teacher'?state.user.uid:state.user.createdBy;
  if(!ownerId){state.customTests=[];return}
  const customDocs=state.user.role==='teacher'
    ?await getDocs(query(collection(db,'tests'),where('teacherId','==',ownerId)))
    :await getDocs(query(collection(db,'tests'),where('status','==','published')));
  state.customTests=customDocs.docs.map(snapshot=>({id:snapshot.id,...snapshot.data()})).filter(test=>test.kind==='custom'&&test.teacherId===ownerId&&test.status==='published'&&Array.isArray(test.questions));
}

async function loadAccountData(){
  if(!state.user)return;
  await loadCustomTests();
  if(state.user.role==='teacher'){
    const [studentDocs,attemptDocs]=await Promise.all([
      getDocs(query(collection(db,"users"),where("createdBy","==",state.user.uid))),
      getDocs(query(collection(db,"attempts"),where("teacherId","==",state.user.uid)))
    ]);
    state.students=studentDocs.docs.map(d=>({id:d.id,...d.data()}));
    state.attempts=attemptDocs.docs.map(d=>({id:d.id,...d.data()}));
  }else{
    const attemptDocs=await getDocs(query(collection(db,"attempts"),where("studentId","==",state.user.uid)));
    state.students=[];
    state.attempts=attemptDocs.docs.map(d=>({id:d.id,...d.data()}));
  }
}

watchAuth(async firebaseUser=>{
  state.authLoading=false;
  if(!firebaseUser){state.user=null;render();return}
  try{
    const profileSnap=await getDoc(doc(db,"users",firebaseUser.uid));
    if(!profileSnap.exists())throw new Error("Профиль пользователя не найден в Firestore");
    const profile=profileSnap.data();
    state.user={uid:firebaseUser.uid,role:profile.role,name:profile.displayName||firebaseUser.displayName||firebaseUser.email,group:profile.groupId||"Без группы",createdBy:profile.createdBy||null,login:profile.login||firebaseUser.email};
    state.role=profile.role;
    state.view=profile.role==='teacher'?'dashboard':'student-home';
    if(profile.role==='teacher'){
      try{await publishBuiltInTests()}catch(syncError){console.error("Не удалось синхронизировать встроенные тесты",syncError);setTimeout(()=>toast('Кабинет открыт, но тесты не удалось синхронизировать'),100)}
    }
    await loadAccountData();
    if(profile.role==='teacher'&&await scoreSubmittedAttempts())await loadAccountData();
    render();
  }catch(error){console.error(error);await logout();state.user=null;render();}
});

window.startTest=startTest;window.createStudentModal=createStudentModal;window.toast=toast;render();
